import { z } from 'zod';

/**
 * POST /api/v1/offers body.
 *
 * idempotencyKey is generated by the client as a UUIDv4 before the request is
 * sent. It is UNIQUE in the database, so a double submit or a network retry can
 * never create two reservations for the same click.
 */
export const CreateOfferBodySchema = z.object({
  needId: z.string().uuid('needId must be a UUID'),
  quantity: z.coerce
    .number()
    .int('quantity must be a whole number')
    .positive('quantity must be greater than zero')
    .max(1_000_000, 'quantity is unrealistically large'),
  idempotencyKey: z.string().uuid('idempotencyKey must be a UUID'),
});

export type CreateOfferBody = z.infer<typeof CreateOfferBodySchema>;

/** How long a reservation holds the stock before it is released. */
export const RESERVATION_DAYS = 7;